  $('#phone-recovery-form')?.addEventListener('submit',e=>{e.preventDefault();$('#recovery-status').textContent='SMS-восстановление пока недоступно: SMS-провайдер ещё не подключён. Не вводи номер повторно до подключения SMS.';});
  $('#phone-bind-form')?.addEventListener('submit',e=>{e.preventDefault();const note=$('#phone-bind-note');note.textContent='Привязка пока не выполняется: серверная SMS-верификация не подключена. Номер не сохранён.';toast('SMS-провайдер ещё не подключён');});
  $('#change-password-form')?.addEventListener('submit',async e=>{e.preventDefault();const current=$('#current-password').value,next=$('#new-password').value,confirm=$('#confirm-new-password').value,status=$('#change-password-status'),button=e.currentTarget.querySelector('button[type=submit]');if(next.length<8){status.textContent='Новый пароль должен содержать минимум 8 символов.';return}if(next!==confirm){status.textContent='Новые пароли не совпадают.';return}button.disabled=true;status.textContent='Обновляю пароль…';try{await api('/account/password',{method:'POST',body:{currentPassword:current,newPassword:next}});status.textContent='Пароль изменён. Другие сессии завершены.';$('#current-password').value='';$('#new-password').value='';$('#confirm-new-password').value='';toast('Пароль успешно изменён')}catch(error){status.textContent=error.message||'Не удалось изменить пароль'}finally{button.disabled=false}});

  function updateAccountUI(account){currentAccount=account;const displayName=account?.displayName||account?.display_name||account?.name||'Пользователь';const username=account?.username||'';const initial=(displayName.trim()[0]||'N').toUpperCase();const nameNode=$('#profile-display-name'),userNode=$('#profile-username'),avatar=$('#profile-avatar');if(nameNode)nameNode.textContent=displayName;if(userNode)userNode.textContent='@'+username;if(avatar){avatar.textContent=initial;const glint=document.createElement('span');glint.className='avatar-glint';avatar.appendChild(glint)}const mini=$('.avatar-mini');if(mini)mini.textContent=initial;const badges=$('#profile-badges');if(badges){badges.innerHTML='';if(account?.role==='owner'){const dev=document.createElement('span');dev.className='profile-badge developer-badge';dev.textContent='✦ DEVELOPER';badges.appendChild(dev);if(account?.premium){const plus=document.createElement('span');plus.className='profile-badge premium-badge';plus.textContent='✦ NEGRAM +';badges.appendChild(plus)}}else if(account?.role==='junior'){const junior=document.createElement('span');junior.className='profile-badge junior-badge';junior.textContent='✧ JUNIOR DEV';badges.appendChild(junior)}else if(account?.premium){const plus=document.createElement('span');plus.className='profile-badge premium-badge';plus.textContent='✦ NEGRAM +';badges.appendChild(plus)}else{const member=document.createElement('span');member.className='profile-badge';member.textContent='NEGRAM MEMBER';badges.appendChild(member)}}const devGroup=$('#developer-settings-group');if(devGroup)devGroup.hidden=!['owner','junior'].includes(account?.role);document.querySelectorAll('[data-owner-only]').forEach(n=>n.hidden=account?.role!=='owner');document.querySelectorAll('[data-junior-only]').forEach(n=>n.hidden=account?.role!=='junior');const bio=$('#profile-bio');if(bio)bio.textContent=account?.bio||'Добавь описание в настройках профиля';$('#profile-name-input').value=displayName;$('#profile-bio-input').value=account?.bio||'';$('#ghost-plus-setting').checked=!!account?.ghost_plus;$('#developer-ghost-toggle').checked=!!account?.ghost_plus;$('#show-online-setting').checked=account?.show_online!==false;const premiumStatus=$('#premium-status');if(premiumStatus)premiumStatus.textContent=account?.premium?'NEGRAM + АКТИВЕН':'PREMIUM НЕ ПОДКЛЮЧЁН';applyProfileAssets()}
  function enterApp(user,token){currentAccount=user;currentToken=token;const tokens=readTokens();tokens[user.username]=token;writeTokens(tokens);localStorage.setItem(activeUserKey,user.username);updateAccountUI(user);document.body.classList.remove('logged-out');authError.textContent='';showAuthMode('login');renderCustomEmojis();go('chats');loadChats().catch(e=>toast('Не удалось загрузить чаты: '+e.message));loadIncomingCalls();api('/presence',{method:'POST',body:{ghostPlus:!!user.ghost_plus,showOnline:user.show_online!==false}}).catch(()=>{});}
  loginForm.addEventListener('submit',async e=>{e.preventDefault();authError.textContent='';const username=$('#login-username').value.trim().toLowerCase(),password=$('#login-password').value;const submit=loginForm.querySelector('button[type="submit"]');submit.disabled=true;try{const result=await api('/login',{method:'POST',auth:false,body:{username,password}});enterApp(result.user,result.token);toast('Вход выполнен · '+username)}catch(err){authError.textContent=err.message||'Не удалось войти. Проверь интернет и данные.'}finally{submit.disabled=false}});
  registerForm.addEventListener('submit',async e=>{e.preventDefault();authError.textContent='';const displayName=$('#register-name').value.trim(),username=$('#register-username').value.trim().toLowerCase(),password=$('#register-password').value,inviteCode=$('#register-invite').value.trim();if(!/^[a-z0-9_]{3,24}$/.test(username)){authError.textContent='Имя пользователя: 3–24 символа, латиница, цифры или _.';return}if(password.length<8){authError.textContent='Пароль должен содержать минимум 8 символов.';return}const submit=registerForm.querySelector('button[type="submit"]');submit.disabled=true;try{const result=await api('/register',{method:'POST',auth:false,body:{username,displayName,password,inviteCode}});enterApp(result.user,result.token);toast('Аккаунт создан на сервере NeGram')}catch(err){authError.textContent=err.message||'Не удалось зарегистрироваться.'}finally{submit.disabled=false}});
  async function restoreSession(){const username=localStorage.getItem(activeUserKey),token=readTokens()[username];if(!username||!token){showAuthMode('login');return}try{const result=await api('/me',{token});enterApp(result.user,token)}catch(error){showAuthMode('login');if(error.status===401){const tokens=readTokens();delete tokens[username];writeTokens(tokens);localStorage.removeItem(activeUserKey);authError.textContent='Сессия завершилась. Войди снова.'}else{authError.textContent='Не удалось связаться с сервером. Проверь интернет и попробуй обновить страницу.'}}}
  $('#switch-account')?.addEventListener('click',async()=>{const tokens=readTokens(),names=Object.keys(tokens);if(names.length>1){const choice=prompt('Сохранённые аккаунты:\n'+names.join('\n')+'\n\nВведи имя аккаунта для переключения или нажми Отмена:');if(choice===null)return;if(choice){const key=choice.trim().toLowerCase(),token=tokens[key];if(!token){toast('Для этого аккаунта нет сохранённой сессии');return}try{const result=await api('/me',{token});enterApp(result.user,token);toast('Переключено на @'+key)}catch{delete tokens[key];writeTokens(tokens);toast('Сессия аккаунта завершилась — войди снова')}return}}localStorage.removeItem(activeUserKey);currentAccount=null;currentToken='';document.body.classList.add('logged-out');$('#login-password').value='';$('#login-username').value='';showAuthMode('login');if(names.length)$('#login-username').value=names[0]});
  const profileAssetsKey=()=>`negram-profile-assets-v2:${currentAccount?.username||'guest'}`;
  function loadProfileAssets(){try{return JSON.parse(localStorage.getItem(profileAssetsKey())||'{}')}catch{return {}}}
  function applyProfileAssets(){const assets=loadProfileAssets(),avatar=$('#profile-avatar'),cover=$('#profile-cover');if(assets.avatarEmoji&&avatar){avatar.textContent=assets.avatarEmoji;const glint=document.createElement('span');glint.className='avatar-glint';avatar.appendChild(glint)}if(assets.avatar&&avatar){avatar.textContent='';const img=document.createElement('img');img.src=assets.avatar;img.alt='Фото профиля';avatar.appendChild(img)}if(assets.cover&&cover){cover.style.backgroundImage=`linear-gradient(90deg,rgba(12,9,29,.25),rgba(12,9,29,.42)),url("${assets.cover}")`;cover.style.backgroundSize='cover';cover.style.backgroundPosition='center'}else if(cover&&assets.coverStyle)cover.style.background=assets.coverStyle}
  function saveProfileAsset(kind,file){if(!file||!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=()=>{const assets=loadProfileAssets();assets[kind]=reader.result;try{localStorage.setItem(profileAssetsKey(),JSON.stringify(assets));applyProfileAssets();toast(kind==='avatar'?'Фото профиля обновлено':'Обложка профиля обновлена')}catch{toast('Файл слишком большой. Выбери фото поменьше.')}};reader.readAsDataURL(file)}
  $('#change-avatar')?.addEventListener('click',()=>$('#avatar-file').click());$('#change-cover')?.addEventListener('click',()=>$('#cover-file').click());$('#avatar-file')?.addEventListener('change',e=>{saveProfileAsset('avatar',e.target.files?.[0]);e.target.value=''});$('#cover-file')?.addEventListener('change',e=>{saveProfileAsset('cover',e.target.files?.[0]);e.target.value=''});
  $('#save-profile')?.addEventListener('click',async()=>{if(!currentAccount)return;const displayName=$('#profile-name-input').value.trim().slice(0,32),bio=$('#profile-bio-input').value.trim().slice(0,160);if(!displayName){toast('Укажи отображаемое имя');return}try{const data=await api('/profile',{method:'PATCH',body:{displayName,bio}});currentAccount={...currentAccount,...(data.user||{}),displayName,bio};updateAccountUI(currentAccount);toast('Профиль сохранён')}catch(e){toast('Сохранение на сервере пока недоступно: обнови Worker 4.1. Изменения не отправлены.')}});
  async function setPresencePreference(key,value){if(!currentAccount)return;try{const body=key==='ghost_plus'?{ghostPlus:value}:{showOnline:value};await api('/presence',{method:'POST',body});currentAccount[key]=value;toast('Настройка приватности сохранена')}catch(e){toast('Нужен сервер NeGram 4.1 для сохранения этой настройки');if(key==='ghost_plus'){$('#ghost-plus-setting').checked=!!currentAccount.ghost_plus;$('#developer-ghost-toggle').checked=!!currentAccount.ghost_plus}else $('#show-online-setting').checked=currentAccount.show_online!==false}}
  $('#ghost-plus-setting')?.addEventListener('change',e=>{if(currentAccount?.role!=='owner'){e.target.checked=false;toast('Ghost Plus доступен только главному разработчику');return}setPresencePreference('ghost_plus',e.target.checked)});
  $('#developer-ghost-toggle')?.addEventListener('change',e=>{if(currentAccount?.role!=='owner'){e.target.checked=false;return}setPresencePreference('ghost_plus',e.target.checked)});
  $('#show-online-setting')?.addEventListener('change',e=>setPresencePreference('show_online',e.target.checked));
  $('#refresh-online-users')?.addEventListener('click',async()=>{const host=$('#online-users-list');host.innerHTML='<p class="muted">Загружаю список…</p>';try{const data=await api('/developer/online');host.innerHTML='';(data.users||[]).forEach(u=>{const row=document.createElement('div');row.className='developer-user-row';row.textContent=(u.displayName||u.display_name||u.username)+' · @'+u.username;host.appendChild(row)});if(!data.users?.length)host.textContent='Сейчас нет пользователей онлайн или они скрыли присутствие.'}catch(e){host.textContent='Список станет доступен после развёртывания Worker 4.1 и миграции D1.'}});
  $('#recommend-junior')?.addEventListener('click',async()=>{const username=$('#junior-candidate').value.trim().replace(/^@/,'').toLowerCase(),reason=$('#junior-reason').value.trim();if(!username){toast('Укажи ник кандидата');return}try{await api('/developer/junior-recommendations',{method:'POST',body:{username,reason}});toast('Рекомендация отправлена');$('#junior-candidate').value='';$('#junior-reason').value=''}catch(e){toast('Отправка рекомендаций появится после обновления Worker 4.1')}});
  $('#load-junior-recommendations')?.addEventListener('click',async()=>{const host=$('#junior-recommendations-list');host.textContent='Загружаю…';try{const data=await api('/developer/junior-recommendations');host.innerHTML='';(data.recommendations||[]).forEach(r=>{const row=document.createElement('div');row.className='developer-user-row';row.textContent='@'+r.username+' · от @'+r.recommended_by+' · '+(r.reason||'без комментария');host.appendChild(row)});if(!data.recommendations?.length)host.textContent='Пока нет рекомендаций'}catch(e){host.textContent='Не удалось загрузить рекомендации'}});
  $('#assign-junior')?.addEventListener('click',async()=>{if(currentAccount?.role!=='owner'){toast('Только NeGramDev может назначать младших разработчиков');return}const username=$('#assign-junior-name').value.trim().replace(/^@/,'').toLowerCase();if(!username)return toast('Укажи ник аккаунта');try{await api('/developer/juniors',{method:'POST',body:{username}});toast('@'+username+' назначен младшим разработчиком');$('#assign-junior-name').value=''}catch(e){toast('Не удалось назначить: '+e.message)}});
  $('#approve-dev-code')?.addEventListener('click',async()=>{if(currentAccount?.role!=='owner'){toast('Только NeGramDev может одобрять коды');return}const code=$('#approve-dev-code-input').value.trim().toUpperCase();if(!code)return toast('Введи код из предложения младшего разработчика');try{await api('/developer/codes/'+encodeURIComponent(code)+'/approve',{method:'POST',body:{}});toast('Код одобрен и активирован');$('#approve-dev-code-input').value=''}catch(e){toast('Не удалось одобрить код: '+e.message)}});
  $('#create-dev-code')?.addEventListener('click',async()=>{const days=Number($('#dev-code-days').value),junior=currentAccount?.role==='junior';if(!Number.isInteger(days)||(junior?(days<1||days>7):(days<7||days>365))){toast(junior?'Младший разработчик может предложить 1–7 дней':'Для NeGramDev срок должен быть от 7 до 365 дней');return}const description=junior?prompt('Опиши назначение кода для NeGramDev:')||'': '';try{const data=await api('/developer/codes',{method:'POST',body:{durationDays:days,description}});$('#dev-code-result').textContent='Код: '+data.code+' · '+days+' дней · '+(data.status==='pending'?'ожидает одобрения':'активен');toast(data.status==='pending'?'Предложение отправлено NeGramDev в личный чат':'Код создан сервером')}catch(e){toast('Создание кодов станет доступно после обновления Worker 4.1')}});
