  async function loadIncomingCalls(){if(!currentToken||activeCall)return;try{const data=await api('/calls/incoming');const host=$('#incoming-calls');host.innerHTML='';const calls=data.calls||[];calls.forEach(call=>{const card=document.createElement('div');card.className='incoming-call-card';const info=document.createElement('div');info.innerHTML='<strong></strong><small></small>';info.querySelector('strong').textContent=call.callerDisplayName||call.callerUsername;info.querySelector('small').textContent=call.kind==='video'?'Видеозвонок':'Голосовой звонок';const accept=document.createElement('button');accept.type='button';accept.textContent='Принять';accept.addEventListener('click',()=>acceptCall(call));const decline=document.createElement('button');decline.type='button';decline.className='decline';decline.textContent='Отклонить';decline.addEventListener('click',()=>api(`/calls/${call.id}/answer`,{method:'POST',body:{action:'decline'}}).then(loadIncomingCalls).catch(e=>toast(e.message)));card.append(info,accept,decline);host.appendChild(card)});const banner=$('#incoming-call-banner');if(calls.length){const call=calls[0];if(visibleIncomingCallId!==call.id){visibleIncomingCallId=call.id;banner.innerHTML='';const label=document.createElement('span');label.textContent=(call.kind==='video'?'Видеозвонок от ':'Звонок от ')+(call.callerDisplayName||call.callerUsername);const accept=document.createElement('button');accept.type='button';accept.textContent='Принять';accept.addEventListener('click',()=>{banner.hidden=true;acceptCall(call)});const decline=document.createElement('button');decline.type='button';decline.textContent='Отклонить';decline.addEventListener('click',()=>api(`/calls/${call.id}/answer`,{method:'POST',body:{action:'decline'}}).then(()=>{banner.hidden=true;visibleIncomingCallId='';loadIncomingCalls()}).catch(e=>toast(e.message)));banner.append(label,accept,decline);banner.hidden=false}}else{banner.hidden=true;visibleIncomingCallId=''}const hist=await api('/calls/history');const hh=$('#calls-history');hh.innerHTML='';if(!hist.calls?.length){hh.innerHTML='<div class="calls-empty">История звонков появится после первых вызовов.</div>'}else hist.calls.forEach(c=>{const row=document.createElement('div');row.className='call-history-row';const info=document.createElement('div');info.innerHTML='<strong></strong><small></small>';info.querySelector('strong').textContent=c.peerDisplayName||c.peerUsername;const when=new Date(safeTimestamp(c.createdAt));info.querySelector('small').textContent=(c.direction==='outgoing'?'Исходящий':'Входящий')+' · '+(c.kind==='video'?'видео':'голос')+' · '+when.toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});const state=document.createElement('span');state.textContent=c.status==='accepted'||c.status==='ended'?'✓':'•';row.append(info,state);hh.appendChild(row)})}catch(e){/* Worker may not yet be deployed */}}
  incomingPoll=setInterval(loadIncomingCalls,3000);
  $('#chat-call-audio')?.addEventListener('click',()=>startCall('audio'));
