  $('#call-camera')?.addEventListener('click',()=>{callCameraOff=!callCameraOff;callStream?.getVideoTracks().forEach(t=>t.enabled=!callCameraOff);$('#call-camera').classList.toggle('is-off',callCameraOff);$('#call-camera').textContent=callCameraOff?'🚫':'▣'});
