  const bubbleNames=['glass','violet','blue','dark','holo','chrome','neon','rose','mint','sunset','carbon','crystal','tiktok','cartoon','roblox','frog','duck','capybara','strongcat','facepalm','pepehearts','pig','shark','heartpepe','pigshark','doge','dino','catdog','tonguebear','frogchick','dachshund','hungrydog','excitedpepe'];
  function setBubble(style,notify=false,saveDefault=true){if(!bubbleNames.includes(style))style='glass';document.body.dataset.bubble=style;$$('.bubble-option').forEach(b=>b.classList.toggle('selected',b.dataset.style===style));if(saveDefault){try{localStorage.setItem('negram-bubble-style',style)}catch{}}const name=$('.bubble-option[data-style="'+style+'"] strong')?.textContent||style;const out=$('#bubble-preview-out'),inside=$('#bubble-preview-in');if(out)out.textContent='Выглядит отлично! 💜';if(inside)inside.textContent='Привет! Это стиль «'+name+'» ✨';if(notify)toast('Пузырь изменён: '+name)}
  $$('.bubble-option').forEach(b=>b.addEventListener('click',()=>{if(bubblePickerForChat&&activeChatId){let saved={};try{saved=JSON.parse(localStorage.getItem('negram-chat-bubbles-v1')||'{}')}catch{}saved[activeChatId]=b.dataset.style;try{localStorage.setItem('negram-chat-bubbles-v1',JSON.stringify(saved))}catch{}setBubble(b.dataset.style,true,false);bubblePickerForChat=false}else setBubble(b.dataset.style,true)}));
  try{setBubble(localStorage.getItem('negram-bubble-style')||'glass')}catch{setBubble('glass')}

  const themeNames=['nebula','deep','aurora','platinum','rose'];
  function setTheme(theme,notify=false){if(!themeNames.includes(theme))theme='nebula';document.body.dataset.theme=theme;$$('.theme-option').forEach(b=>b.classList.toggle('selected',b.dataset.theme===theme));try{localStorage.setItem('negram-theme',theme)}catch{};if(notify)toast('Тема оформления применена')}
  $$('.theme-option').forEach(b=>b.addEventListener('click',()=>setTheme(b.dataset.theme,true)));
  try{setTheme(localStorage.getItem('negram-theme')||'nebula')}catch{setTheme('nebula')}

  $('#theme-toggle').addEventListener('click',()=>{document.body.classList.toggle('glow-off');$('#glow-toggle').classList.toggle('on');try{localStorage.setItem('negram-glow',document.body.classList.contains('glow-off')?'off':'on')}catch{}});
  try{if(localStorage.getItem('negram-glow')==='off'){document.body.classList.add('glow-off');$('#glow-toggle').classList.remove('on')}}catch{}
  $('#install-help').addEventListener('click',()=>toast('В Safari нажми «Поделиться» → «На экран Домой»'));
  $('#about-button').addEventListener('click',()=>toast('NeGram 4.2 DEV · live chat update'));

  $('#premium-activate-form')?.addEventListener('submit',async e=>{e.preventDefault();const code=$('#premium-code-input').value.trim().toUpperCase(),status=$('#premium-activate-status'),button=$('#activate-premium-code');if(!code)return;button.disabled=true;status.textContent='Проверяю код на сервере…';try{const data=await api('/subscriptions/activate',{method:'POST',body:{code}});currentAccount={...currentAccount,premium:true,premium_until:data.premiumUntil};updateAccountUI(currentAccount);status.textContent='NeGram + активирован до '+new Date(data.premiumUntil).toLocaleDateString('ru-RU');$('#premium-code-input').value='';toast('Подписка NeGram + активирована')}catch(err){status.textContent=err.message||'Не удалось активировать код'}finally{button.disabled=false}});
  const premiumButton=$('#premium-demo-toggle');if(premiumButton){premiumButton.disabled=true;premiumButton.textContent='Покупка появится после подключения платёжной системы';}

  // NeGram 0.8: 50 animated face emojis. They enter the composer and are sent through the chat API as text.
  const faceEmojis=[['😂','Смеюсь'],['🤣','Очень смешно'],['😆','Хохочу'],['😅','Неловко'],['😊','Улыбка'],['🥰','Обожаю'],['😍','Восторг'],['😘','Поцелуй'],['😎','Круто'],['🤩','Вау'],['🥳','Праздник'],['😜','Дразнюсь'],['🤪','Безуминка'],['🤗','Обнимашки'],['🥺','Пожалуйста'],['😭','Плачу'],['😢','Грущу'],['😤','Фыркаю'],['😡','Злюсь'],['🤬','Очень злюсь'],['🤔','Думаю'],['🫣','Подглядываю'],['🫢','Ой'],['😱','Испуг'],['🤯','Взрыв мозга'],['😴','Сплю'],['🥱','Зеваю'],['🤧','Апчхи'],['🤒','Приболел'],['🤓','Умничаю'],['🤑','Деньги'],['🤠','Ковбой'],['👻','Привидение'],['🤖','Робот'],['💀','Череп'],['🤡','Клоун'],['😇','Ангел'],['🙃','Вверх ногами'],['😏','Хитрюга'],['😶','Без слов'],['🫡','На связи'],['🤝','Договорились'],['🙄','Ну конечно'],['😬','Неловко'],['😋','Вкусно'],['🤤','Хочу'],['🥹','До слёз'],['😈','Озорник'],['💩','Какашка'],['🐸','Лягушка'],['🫠','Растаял'],['🥸','Маскировка'],['🫨','Тряска'],['🧌','Тролль'],['🦆','Утёнок'],['🦫','Капибара'],['🐈‍⬛','Чёрный кот'],['🦈','Акула'],['🐷','Поросёнок'],['🐶','Пёсель'],['🐻‍❄️','Белый медведь'],['🦖','Динозавр'],['🦝','Енот'],['🦥','Ленивец'],['🐙','Осьминог'],['🦭','Тюлень'],['🐧','Пингвин']];
  const faceGrid=$('#animated-faces-grid');faceEmojis.forEach(([emoji,label])=>{const b=document.createElement('button');b.type='button';b.className='animated-face-card';const face=document.createElement('span');face.className='emoji';face.textContent=emoji;const caption=document.createElement('small');caption.textContent=label;b.append(face,caption);b.addEventListener('click',()=>{go('chat');const input=$('#message-input');input.value=(input.value?input.value+' ':'')+emoji;input.focus()});faceGrid?.appendChild(b)});
  let emojiSourceImage=null,emojiSourceUrl=null;
  const customEmojiKey=()=>`negram-custom-emojis-v2:${currentAccount?.username||'guest'}`;
  function getCustomEmojis(){try{const v=JSON.parse(localStorage.getItem(customEmojiKey())||'[]');return Array.isArray(v)?v:[]}catch{return []}}
  function drawEmojiCrop(){const canvas=$('#emojiCropCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,256);if(!emojiSourceImage){ctx.fillStyle='#b8a9d2';ctx.font='14px system-ui';ctx.textAlign='center';ctx.fillText('Нет картинки',128,132);return}const w=emojiSourceImage.naturalWidth,h=emojiSourceImage.naturalHeight,base=Math.max(256/w,256/h),zoom=Number($('#emojiZoom').value||1),dw=w*base*zoom,dh=h*base*zoom;ctx.save();ctx.beginPath();ctx.rect(0,0,256,256);ctx.clip();ctx.drawImage(emojiSourceImage,(256-dw)/2,(256-dh)/2,dw,dh);ctx.restore()}
  function renderCustomEmojis(){const grid=$('#customEmojiGrid');if(!grid)return;grid.innerHTML='';const items=getCustomEmojis();$('#customEmojiCount').textContent=items.length+' / 30';items.forEach(item=>{const b=document.createElement('button');b.type='button';b.className='animated-face-card custom-emoji-item';const img=document.createElement('img');img.src=item.data;img.alt=item.name;const label=document.createElement('small');label.textContent=item.name;b.append(img,label);b.addEventListener('click',()=>{go('chat');const input=$('#message-input');input.value=(input.value?input.value+' ':'')+`:${item.name}:`;input.focus();toast('В чат вставлено имя эмодзи. Для передачи картинки всем участникам нужно подключить медиахранилище.')});const del=document.createElement('button');del.type='button';del.className='remove-emoji';del.textContent='×';del.addEventListener('click',e=>{e.stopPropagation();localStorage.setItem(customEmojiKey(),JSON.stringify(getCustomEmojis().filter(x=>x.id!==item.id)));renderCustomEmojis()});b.appendChild(del);grid.appendChild(b)})}
  $('#customEmojiFile')?.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>8*1024*1024){toast('Выбери PNG, JPG, WEBP или GIF до 8 МБ');e.target.value='';return}if(emojiSourceUrl)URL.revokeObjectURL(emojiSourceUrl);emojiSourceUrl=URL.createObjectURL(file);const img=new Image();img.onload=()=>{emojiSourceImage=img;$('#emojiZoom').value='1';drawEmojiCrop();$('#saveCustomEmoji').disabled=false;$('#emojiCropHint').textContent=file.type==='image/gif'?'GIF: сохраняется первый кадр':'Предпросмотр готов'};img.onerror=()=>toast('Не удалось открыть картинку');img.src=emojiSourceUrl});
  $('#emojiZoom')?.addEventListener('input',drawEmojiCrop);
  $('#saveCustomEmoji')?.addEventListener('click',()=>{if(!emojiSourceImage)return;const items=getCustomEmojis();if(items.length>=30){toast('Максимум 30 своих эмодзи');return}const name=($('#customEmojiName').value||'Моё эмодзи').trim().slice(0,24),data=$('#emojiCropCanvas').toDataURL('image/png');try{items.push({id:Date.now().toString(36),name,data});localStorage.setItem(customEmojiKey(),JSON.stringify(items));renderCustomEmojis();toast('Эмодзи сохранено на этом устройстве')}catch{toast('Не хватило места в памяти браузера')}});
  $('#resetCustomEmoji')?.addEventListener('click',()=>{emojiSourceImage=null;if(emojiSourceUrl)URL.revokeObjectURL(emojiSourceUrl);emojiSourceUrl=null;$('#customEmojiFile').value='';$('#customEmojiName').value='';$('#emojiZoom').value='1';$('#saveCustomEmoji').disabled=true;$('#emojiCropHint').textContent='Здесь появится предпросмотр';drawEmojiCrop()});
  renderCustomEmojis();drawEmojiCrop();

  setInterval(()=>{if(currentToken&&!document.hidden)api('/presence',{method:'POST',body:{ghostPlus:!!currentAccount?.ghost_plus,showOnline:currentAccount?.show_online!==false}}).catch(()=>{})},30000);
    if('serviceWorker' in navigator && location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
  render();
